import {useEffect,useRef,useState} from 'react';import './DashboardPage.css';import{Routes,Route,Navigate,Link,NavLink,useLocation,useNavigate,useParams}from'react-router-dom';import{motion,AnimatePresence}from'framer-motion';import{ShieldCheck,LayoutDashboard,Globe,ScanLine,AlertTriangle,ListTodo,Bell,FileText,Settings,Users,Activity,LogOut,Menu,X,Plus,Search,ArrowUpRight,CheckCircle2,Clock3,ShieldAlert,Sun,Moon,LockKeyhole,ChevronRight,RefreshCw,Download,Trash2,Play,Pause,ExternalLink,Pencil,Eye,EyeOff,CalendarClock,Building2,KeyRound,BookOpen,Sparkles}from'lucide-react';import{BarChart,Bar,XAxis,YAxis,Tooltip,ResponsiveContainer,PieChart,Pie,Cell}from'recharts';import{api,getData,send}from'../services/api';import{PageHeader,StatCard,Loading,ErrorState,Empty}from'../components/common';import{useAuth}from'../context/AuthContext';import{SchedulesPage,OrganizationsPage,IntegrationsPage,SecurityCenterPage,HelpCenterPage}from'./EnterprisePages.jsx';import AICopilotPage from './AICopilotPage.jsx';
