function App(){const{user,logout}=useAuth();const loc=useLocation();const[mobile,setMobile]=useState(false);const[palette,setPalette]=useState(false);const[unreadCount,setUnreadCount]=useState(0);const[loggingOut,setLoggingOut]=useState(false);const[theme,setTheme]=useState(localStorage.getItem('st-theme')||'dark');const navigate=useNavigate();const handleTopbarLogout=async()=>{if(loggingOut)return;const confirmed=window.confirm('Are you sure you want to log out of SecureTrack?');if(!confirmed)return;setLoggingOut(true);try{await logout();navigate('/login',{replace:true});}catch(error){console.error('SecureTrack logout failed:',error);window.alert('Logout could not be completed. Please try again.');}finally{setLoggingOut(false);}};useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('st-theme',theme)},[theme]);useEffect(()=>setMobile(false),[loc.pathname]);useEffect(()=>{const onKey=(e)=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setPalette(v=>!v)}if(e.key==='Escape')setPalette(false)};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey)},[]);useEffect(()=>{if(!user)return;let active=true;const refreshCount=()=>getData('/notifications',{limit:100}).then(d=>{if(active)setUnreadCount((d.items||[]).filter(n=>!n.readAt).length)}).catch(()=>{});refreshCount();window.addEventListener('securetrack:notifications-changed',refreshCount);return()=>{active=false;window.removeEventListener('securetrack:notifications-changed',refreshCount)}},[user,loc.pathname]);return <Routes><Route path="/" element={<Landing/>}/><Route path="/features" element={<PublicPage title="Security clarity, without the noise" text="Track availability, TLS certificate health, redirects and recommended HTTP security headers from one calm workspace."/>}/><Route path="/how-it-works" element={<PublicPage title="Monitor. Understand. Improve." text="Register an authorized website, run a passive check, review evidence, then turn findings into trackable remediation tasks."/>}/><Route path="/pricing" element={<PublicPage title="Plans for every security team" text="Starter and Team plan descriptions are illustrative demo plans; billing and subscriptions are not enabled in this version."/>}/><Route path="/contact" element={<PublicPage title="Talk to SecureTrack" text="For this local starter, contact forms are not connected to a mail service. Configure SMTP before enabling delivery."/>}/><Route path="/privacy" element={<PublicPage title="Privacy policy" text="SecureTrack stores account and monitoring records in your configured MongoDB database. Only monitor domains you own or are explicitly authorized to assess."/>}/><Route path="/terms" element={<PublicPage title="Terms of service" text="Use SecureTrack only for authorized passive monitoring. You are responsible for target authorization, deployment configuration and retention policy."/>}/><Route path="/login" element={<AuthPage mode="login"/>}/><Route path="/register" element={<AuthPage mode="register"/>}/><Route path="/forgot-password" element={<PublicPage title="Password recovery" text="Password reset email delivery is not configured in this starter. Use account settings to change your password while signed in."/>}/><Route path="/reset-password" element={<PublicPage title="Reset password" text="Password reset token workflow requires SMTP delivery and is not enabled in this starter."/>}/><Route path="/app/*" element={<Guard><div className="app-shell"><aside className={`sidebar ${mobile?'open':''}`}><div className="brand"><span className="brand-icon"><ShieldCheck size={22}/></span><span>Secure<span className="brand-blue">Track</span><small>SECURITY WORKSPACE</small></span><button className="icon-btn mobile-close" onClick={()=>setMobile(false)}><X/></button></div><div className="workspace-label">WORKSPACE</div><nav>{nav.map(([label,path,Icon])=><NavLink end={path==='/app'} to={path} key={path} className={({isActive})=>'nav-item '+(isActive?'active':'')}><Icon size={18}/><span>{label}</span>{label==='Notifications'&&unreadCount>0&&<span className="nav-count">{unreadCount>99?'99+':unreadCount}</span>}{label==='Findings'&&<span className="nav-dot"/>}</NavLink>)}</nav><div className="sidebar-bottom"><div className="secure-card"><div className="secure-mark"><LockKeyhole size={16}/></div><b>You're in control</b><p>Only monitor websites you're authorized to assess.</p></div><button className="nav-item" onClick={async()=>{await logout()}}><LogOut size={18}/><span>Sign out</span></button></div></aside>{mobile&&<div className="scrim" onClick={()=>setMobile(false)}/>}<main className="main-area"><header className="topbar"><button className="icon-btn menu-btn" onClick={()=>setMobile(true)}><Menu/></button><div className="crumb">Workspace <ChevronRight size={14}/> <span>{nav.find(n=>loc.pathname===n[1])?.[0]||'Security center'}</span></div><button className="global-search-trigger" onClick={()=>setPalette(true)} aria-label="Open quick search"><Search size={16}/><span>Search pages and actions</span><kbd>⌘ K</kbd></button><div className="top-actions"><span className="status-pill"><span className="green-dot"/> Systems operational</span><button className="icon-btn" aria-label="Toggle theme" onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={18}/>:<Moon size={18}/>}</button><Link className="avatar" to="/app/settings" aria-label="Open account settings" title={user?.name||user?.email||'Account settings'}>{(user?.name||'U').slice(0,1).toUpperCase()}</Link><button type="button" className="topbar-logout" onClick={handleTopbarLogout} disabled={loggingOut} aria-label="Log out of SecureTrack" title="Log out">{loggingOut?<span className="topbar-logout-spinner" aria-hidden="true"/>:<LogOut size={16} aria-hidden="true"/>}<span>{loggingOut?'Logging out…':'Logout'}</span></button></div></header><div className="page-wrap"><AnimatePresence mode="wait"><motion.div key={loc.pathname} initial={{opacity:0,y:8}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-5}} transition={{duration:.18}}><Routes><Route index element={<Dashboard/>}/><Route path="ai-copilot" element={<AICopilotPage/>}/><Route path="websites" element={<Websites/>}/><Route path="websites/new" element={<WebsiteForm/>}/><Route path="websites/:id/edit" element={<WebsiteEditForm/>}/><Route path="websites/:id" element={<WebsiteDetail/>}/><Route path="scans" element={<Scans/>}/><Route path="findings" element={<Findings/>}/><Route path="risk-intelligence" element={<RiskIntelligence/>}/><Route path="changes" element={<ChangeHistory/>}/><Route path="tasks" element={<Tasks/>}/><Route path="reports" element={<Reports/>}/><Route path="notifications" element={<Notifications/>}/><Route path="audit-logs" element={<Audit/>}/><Route path="schedules" element={<SchedulesPage/>}/><Route path="organizations" element={<OrganizationsPage/>}/><Route path="integrations" element={<IntegrationsPage/>}/><Route path="security-center" element={<SecurityCenterPage/>}/><Route path="help" element={<HelpCenterPage/>}/><Route path="settings" element={<SettingsPage/>}/><Route path="*" element={<NotFound/>}/></Routes></motion.div></AnimatePresence></div><footer className="footer"><span>© 2026 SecureTrack</span><span><ShieldCheck size={13}/> Passive security posture monitoring</span></footer></main></div>{palette&&<CommandPalette onClose={()=>setPalette(false)}/>}</Guard>}/><Route path="*" element={<NotFound publicPage/>}/></Routes>}
