export function WebsiteDetail(){const{id}=useParamsHook(),nav=useNavigate(),[w,setW]=useState(null),[scans,setScans]=useState([]),[busy,setBusy]=useState(true);function load(){setBusy(true);Promise.all([getData(`/websites/${id}`),getData('/scans',{limit:50})]).then(([a,b])=>{setW(a.item);setScans((b.items||[]).filter(s=>String(s.website?._id||s.website)===id))}).catch(()=>toast.error('Could not load website details')).finally(()=>setBusy(false))}useEffect(()=>{load()},[id]);async function scan(){try{await api.post('/scans',{websiteId:id});toast.success('Scan started. Results appear when checks finish.');setTimeout(load,1000)}catch(e){toast.error(e.response?.data?.message||'Could not start scan')}}if(busy)return <Loading/>;if(!w)return <Empty title="Website not found" text="This website may have been removed."/>;return <><PageHeader eyebrow="WEBSITE DETAILS" title={w.name} subtitle={w.url} action={<><button className="btn secondary" onClick={scan}><Play size={16}/> Run scan</button><Link className="btn ghost" to={`/app/websites/${id}/edit`}><Pencil size={15}/> Edit</Link><Link className="btn ghost" to="/app/websites">Back</Link></>}/><div className="stat-grid"><StatCard title="Monitoring" value={w.monitoringEnabled?'Active':'Paused'} sub="Monitoring preference" icon={Activity}/><StatCard title="Latest status" value={w.latestStatus} sub="Based on last completed scan" icon={ShieldCheck} tone="cyan"/><StatCard title="Total scans" value={scans.length} sub="Stored scan history" icon={ScanLine} tone="violet"/><StatCard title="Last checked" value={w.lastCheckedAt?new Date(w.lastCheckedAt).toLocaleDateString():'Never'} sub="Latest check timestamp" icon={Clock3} tone="orange"/></div><section className="panel table-panel"><div className="panel-heading"><div><h3>Scan history</h3><p>Checks run for this website</p></div></div><ScanTable items={scans}/></section></>}
