export function Scans(){const[data,setData]=useState([]),[loading,setLoading]=useState(true),[websites,setWebsites]=useState([]),[selected,setSelected]=useState('');const load=()=>{setLoading(true);Promise.all([getData('/scans',{limit:100}),getData('/websites',{limit:100})]).then(([a,b])=>{setData(a.items||[]);setWebsites(b.items||[]);if(!selected&&b.items?.length)setSelected(b.items[0]._id)}).catch(e=>toast.error(e.response?.data?.message||'Could not load scans')).finally(()=>setLoading(false))};useEffect(()=>{load()},[]);async function run(){if(!selected)return toast.error('Add a website first');try{await api.post('/scans',{websiteId:selected});toast.success('Scan queued; results will be saved after checks finish');setTimeout(load,900)}catch(e){toast.error(e.response?.data?.message||'Scan could not start')}}return <><PageHeader eyebrow="MONITORING ENGINE" title="Security scans" subtitle="Run and review passive checks against your authorized websites." action={<button className="btn primary" onClick={run}><Play size={16}/> Start scan</button>}/><div className="panel list-panel"><div className="list-toolbar"><div className="select-wrap"><Globe size={16}/><select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Select a website</option>{websites.map(w=><option key={w._id} value={w._id}>{w.name}</option>)}</select></div><button className="btn secondary small" onClick={load}><RefreshCw size={15}/> Refresh</button></div>{loading?<Loading/>:!data.length?<Empty title="No scan history" text="Choose a website and start your first scan."/>:<div className="table-scroll"><table><thead><tr><th>Website</th><th>Status</th><th>Risk score</th><th>Checks</th><th>Created</th></tr></thead><tbody>{data.map(s=><tr key={s._id}><td><b>{websites.find(w=>w._id===(s.website?._id||s.website))?.name||s.website?.name||'Website'}</b><small>{s.summary||'Passive security check'}</small></td><td><span className={'badge '+s.status}>{s.status}</span></td><td><span className="risk-score">{s.riskScore??'—'}<small>/100</small></span></td><td>{s.checks?.length||0}</td><td>{new Date(s.createdAt).toLocaleString()}</td></tr>)}</tbody></table></div>}</div><div className="notice"><ShieldCheck size={18}/><p><b>Scope:</b> SecureTrack checks HTTPS availability, HTTP status, selected security headers, redirect behavior, response time and TLS certificate metadata. It does not exploit vulnerabilities.</p></div></>}
export function Findings(){const[data,setData]=useState([]),[loading,setLoading]=useState(true),[filter,setFilter]=useState('');const load=()=>{setLoading(true);getData('/findings',{limit:100,...(filter?{severity:filter}:{})}).then(d=>setData(d.items||[])).catch(e=>toast.error(e.response?.data?.message||'Could not load findings')).finally(()=>setLoading(false))};useEffect(()=>{load()},[filter]);async function update(f,status){try{const r=await api.patch(`/findings/${f._id}`,{status});setData(a=>a.map(x=>x._id===f._id?r.data.data.item:x));toast.success('Finding updated')}catch(e){toast.error(e.response?.data?.message||'Update failed')}}return <><PageHeader eyebrow="RISK & REMEDIATION" title="Security findings" subtitle="Review evidence from completed checks and track the response."/><div className="panel list-panel"><div className="list-toolbar"><div className="select-wrap"><AlertTriangle size={16}/><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="">All severities</option>{['critical','high','medium','low','info'].map(v=><option key={v} value={v}>{v}</option>)}</select></div><span className="muted">{data.length} findings</span></div>{loading?<Loading/>:!data.length?<Empty title="No findings to review" text="Run a scan to generate evidence-backed security findings."/>:<div className="table-scroll"><table><thead><tr><th>Finding</th><th>Severity</th><th>Status</th><th>Evidence</th><th>Action</th></tr></thead><tbody>{data.map(f=><tr key={f._id}><td><b>{f.title}</b><small>{f.description}</small></td><td><span className={'badge '+f.severity}>{f.severity}</span></td><td><span className={'badge '+f.status}>{f.status.replace('_',' ')}</span></td><td><small>{f.evidence?.url||f.evidence?.missing?.join(', ')||'See scan evidence'}</small></td><td><select className="inline-select" value={f.status} onChange={e=>update(f,e.target.value)}><option value="open">Open</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="accepted">Accepted</option></select></td></tr>)}</tbody></table></div>}</div></>}
export function Tasks(){const[data,setData]=useState([]),[loading,setLoading]=useState(true),[show,setShow]=useState(false);const load=()=>{setLoading(true);getData('/tasks',{limit:100}).then(d=>setData(d.items||[])).catch(e=>toast.error(e.response?.data?.message||'Could not load tasks')).finally(()=>setLoading(false))};useEffect(()=>{load()},[]);async function submit(e){e.preventDefault();const f=new FormData(e.currentTarget);try{await api.post('/tasks',{title:f.get('title'),description:f.get('description'),priority:f.get('priority')});toast.success('Task created');setShow(false);load()}catch(e){toast.error(e.response?.data?.message||'Task creation failed')}}async function status(t,v){try{const r=await api.patch(`/tasks/${t._id}`,{status:v});setData(a=>a.map(x=>x._id===t._id?r.data.data.item:x));toast.success('Task updated')}catch(e){toast.error('Could not update task')}}async function del(t){if(!confirm(`Delete task “${t.title}”?`))return;try{await api.delete(`/tasks/${t._id}`);setData(a=>a.filter(x=>x._id!==t._id));toast.success('Task deleted')}catch(e){toast.error('Could not delete task')}}return <><PageHeader eyebrow="REMEDIATION WORKFLOW" title="Remediation tasks" subtitle="Turn security observations into accountable next steps." action={<button className="btn primary" onClick={()=>setShow(true)}><Plus size={16}/> New task</button>}/>{show&&<div className="modal-backdrop"><form className="panel modal-card" onSubmit={submit}><button type="button" className="modal-x icon-btn" onClick={()=>setShow(false)}><X/></button><h2>Create remediation task</h2><p>Record the action you want to track.</p><label>Task title<input name="title" required minLength="2" maxLength="200" placeholder="Enable recommended security headers"/></label><label>Description<textarea name="description" rows="3" placeholder="What needs to be done?"/></label><label>Priority<select name="priority"><option>medium</option><option>low</option><option>high</option><option>urgent</option></select></label><div className="form-actions"><button type="button" className="btn ghost" onClick={()=>setShow(false)}>Cancel</button><button className="btn primary">Create task</button></div></form></div>}<div className="panel list-panel">{loading?<Loading/>:!data.length?<Empty title="No remediation tasks" text="Create a task to track the work required to address a finding."/>:<div className="table-scroll"><table><thead><tr><th>Task</th><th>Priority</th><th>Status</th><th>Due date</th><th>Action</th></tr></thead><tbody>{data.map(t=><tr key={t._id}><td><b>{t.title}</b><small>{t.description||'No description'}</small></td><td><span className={'badge '+t.priority}>{t.priority}</span></td><td><select className="inline-select" value={t.status} onChange={e=>status(t,e.target.value)}>{['open','in_progress','resolved','cancelled'].map(s=><option key={s} value={s}>{s.replace('_',' ')}</option>)}</select></td><td>{t.dueDate?new Date(t.dueDate).toLocaleDateString():'—'}</td><td><button className="icon-btn danger" onClick={()=>del(t)}><Trash2 size={16}/></button></td></tr>)}</tbody></table></div>}</div></>}
export function Reports(){const[data,setData]=useState([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false);const load=()=>{setLoading(true);getData('/reports').then(d=>setData(d.items||[])).catch(e=>toast.error(e.response?.data?.message||'Could not load reports')).finally(()=>setLoading(false))};useEffect(()=>{load()},[]);async function generate(){setBusy(true);try{await api.post('/reports');toast.success('Report generated from stored records');load()}catch(e){toast.error(e.response?.data?.message||'Report generation failed')}finally{setBusy(false)}}async function download(r){try{const res=await api.get(`/reports/${r._id}/csv`,{responseType:'blob'});const url=URL.createObjectURL(res.data);const a=document.createElement('a');a.href=url;a.download=`securetrack-report-${r._id}.csv`;a.click();URL.revokeObjectURL(url)}catch(e){toast.error('Could not download report')}}return <><PageHeader eyebrow="REPORTING" title="Reports" subtitle="Generate downloadable CSV exports from your stored monitoring data." action={<button className="btn primary" disabled={busy} onClick={generate}><Plus size={16}/>{busy?'Generating…':'Generate report'}</button>}/><div className="panel list-panel">{loading?<Loading/>:!data.length?<Empty title="No reports generated" text="Create a report to export your current websites, scans, findings and tasks."/>:<div className="table-scroll"><table><thead><tr><th>Report</th><th>Format</th><th>Records</th><th>Generated</th><th>Download</th></tr></thead><tbody>{data.map(r=><tr key={r._id}><td><b>{r.title}</b><small>{r._id}</small></td><td><span className="badge completed">{r.format.toUpperCase()}</span></td><td>{r.rowCount}</td><td>{new Date(r.generatedAt||r.createdAt).toLocaleString()}</td><td><button className="btn secondary small" onClick={()=>download(r)}><Download size={15}/> CSV</button></td></tr>)}</tbody></table></div>}</div></>}
export function Notifications(){const[data,setData]=useState([]),[loading,setLoading]=useState(true);const load=()=>{setLoading(true);getData('/notifications',{limit:100}).then(d=>setData(d.items||[])).catch(e=>toast.error(e.response?.data?.message||'Could not load notifications')).finally(()=>setLoading(false))};useEffect(()=>{load()},[]);async function read(n){try{const r=await api.patch(`/notifications/${n._id}`);setData(a=>a.map(x=>x._id===n._id?r.data.data.item:x));window.dispatchEvent(new Event('securetrack:notifications-changed'))}catch{toast.error('Could not update notification')}}async function allRead(){try{await api.patch('/notifications/read-all');setData(a=>a.map(x=>({...x,readAt:x.readAt||new Date().toISOString()})));window.dispatchEvent(new Event('securetrack:notifications-changed'));toast.success('All notifications marked read')}catch{toast.error('Could not update notifications')}}return <><PageHeader eyebrow="WORKSPACE UPDATES" title="Notifications" subtitle="Security events and system updates for your account." action={<button className="btn secondary" onClick={allRead}><CheckCircle2 size={16}/> Mark all read</button>}/><div className="panel notification-list">{loading?<Loading/>:!data.length?<Empty title="You're all caught up" text="Scan completions and security events will appear here."/>:data.map(n=><div className={'notification-row '+(!n.readAt?'unread':'')} key={n._id}><span className="notification-icon"><Bell size={18}/></span><div><b>{n.title}</b><p>{n.message}</p><small>{new Date(n.createdAt).toLocaleString()} · {n.category}</small></div>{!n.readAt&&<button className="btn secondary small" onClick={()=>read(n)}>Mark read</button>}</div>)}</div></>}
export function Audit(){const[data,setData]=useState([]),[loading,setLoading]=useState(true);useEffect(()=>{getData('/audit-logs',{limit:100}).then(d=>setData(d.items||[])).catch(()=>toast.error('Could not load audit logs')).finally(()=>setLoading(false))},[]);return <><PageHeader eyebrow="ACCOUNTABILITY" title="Activity logs" subtitle="A record of important actions in your workspace."/><div className="panel list-panel">{loading?<Loading/>:!data.length?<Empty title="No activity recorded" text="Your account actions and scan activity will be listed here."/>:<div className="table-scroll"><table><thead><tr><th>Action</th><th>Resource</th><th>IP address</th><th>Time</th></tr></thead><tbody>{data.map(a=><tr key={a._id}><td><b>{a.action}</b></td><td>{a.resource||'—'} <small>{a.resourceId}</small></td><td>{a.ip||'—'}</td><td>{new Date(a.createdAt).toLocaleString()}</td></tr>)}</tbody></table></div>}</div></>}
export function RiskIntelligence(){
 const [findings,setFindings]=useState([]),[websites,setWebsites]=useState([]),[loading,setLoading]=useState(true),[error,setError]=useState('');
 const load=()=>{setLoading(true);setError('');Promise.all([getData('/findings',{limit:200}),getData('/websites',{limit:200})]).then(([f,w])=>{setFindings(f.items||[]);setWebsites(w.items||[])}).catch(e=>setError(e.response?.data?.message||'Risk intelligence could not be loaded')).finally(()=>setLoading(false))};
 useEffect(()=>{load()},[]);
 const active=findings.filter(f=>!['resolved','accepted'].includes(f.status));
 const weights={critical:5,high:4,medium:3,low:2,info:1};
 const counts=['critical','high','medium','low','info'].map(severity=>({severity,count:active.filter(f=>f.severity===severity).length}));
 const priority=[...active].sort((a,b)=>(weights[b.severity]||0)-(weights[a.severity]||0)||new Date(b.updatedAt||b.createdAt)-new Date(a.updatedAt||a.createdAt)).slice(0,8);
 return <><PageHeader eyebrow="RISK & PRIORITIZATION" title="Risk intelligence" subtitle="Prioritize unresolved findings using their recorded severity and evidence." action={<button className="btn secondary" onClick={load}><RefreshCw size={16}/> Refresh data</button>}/>{loading?<Loading/>:error?<ErrorState message={error} retry={load}/>:<><div className="stat-grid"><StatCard title="Websites in scope" value={websites.length} sub="Registered monitoring targets" icon={Globe}/><StatCard title="Active findings" value={active.length} sub="Excludes resolved and accepted" icon={ShieldAlert} tone="orange"/><StatCard title="Critical findings" value={active.filter(f=>f.severity==='critical').length} sub="Review these first" icon={AlertTriangle} tone="orange"/><StatCard title="Resolved findings" value={findings.filter(f=>f.status==='resolved').length} sub="Marked resolved by a user" icon={CheckCircle2} tone="cyan"/></div><div className="risk-intelligence-grid"><section className="panel"><div className="panel-heading"><div><h3>Severity distribution</h3><p>Unresolved findings only</p></div></div><div className="risk-bars">{counts.map(({severity,count})=><div className="risk-bar-row" key={severity}><span className={'severity-dot '+severity}/><span className="risk-bar-label">{severity}</span><div className="risk-bar-track"><span className={'risk-bar-fill '+severity} style={{width:`${active.length?Math.max(count/active.length*100,count?4:0):0}%`}}/></div><b>{count}</b></div>)}</div><p className="muted risk-footnote">This view uses the scanner's recorded severity labels. It is a prioritization aid, not a formal risk or compliance certification.</p></section><section className="panel"><div className="panel-heading"><div><h3>Recommended review order</h3><p>Highest severity first, then most recently updated</p></div></div>{priority.length?<div className="risk-priority-list">{priority.map((f,i)=><div className="risk-priority-row" key={f._id}><span className="priority-rank">{String(i+1).padStart(2,'0')}</span><span className={'severity-dot '+f.severity}/><div className="risk-priority-copy"><b>{f.title}</b><small>{f.website?.name||websites.find(w=>w._id===(f.website?._id||f.website))?.name||'Website'} · {f.status?.replace('_',' ')||'open'}</small></div><span className={'badge '+f.severity}>{f.severity}</span></div>)}</div>:<Empty title="No active findings" text="Run a scan on an authorized website to build your risk overview."/>}</section></div></>}</>;
}

export function ChangeHistory(){
 const [scans,setScans]=useState([]),[loading,setLoading]=useState(true),[error,setError]=useState('');
 const load=()=>{setLoading(true);setError('');getData('/scans',{limit:200}).then(d=>setScans((d.items||[]).filter(s=>s.status==='completed'))).catch(e=>setError(e.response?.data?.message||'Scan history could not be loaded')).finally(()=>setLoading(false));};
 useEffect(()=>{load()},[]);
 const groups=new Map();
 for(const scan of [...scans].sort((a,b)=>new Date(b.completedAt||b.createdAt)-new Date(a.completedAt||a.createdAt))){const id=scan.website?._id||scan.website;if(!id)continue;if(!groups.has(String(id)))groups.set(String(id),[]);groups.get(String(id)).push(scan)}
 const comparisons=[];
 for(const [websiteId,items] of groups){if(items.length<2)continue;const [current,previous]=items;const keyOf=c=>String(c.key||c.label||c.name||c.title||'check');const prev=new Map((previous.checks||[]).map(c=>[keyOf(c),c]));for(const check of current.checks||[]){const before=prev.get(keyOf(check));if(before&&before.status!==check.status)comparisons.push({id:`${current._id}-${keyOf(check)}`,website:current.website?.name||'Website',label:check.label||check.title||keyOf(check),before:before.status,after:check.status,date:current.completedAt||current.createdAt,scanId:current._id})}}
 return <><PageHeader eyebrow="HISTORICAL OBSERVATIONS" title="Change history" subtitle="Compare completed scans for the same website and review check-status changes." action={<button className="btn secondary" onClick={load}><RefreshCw size={16}/> Refresh history</button>}/>{loading?<Loading/>:error?<ErrorState message={error} retry={load}/>:<><div className="stat-grid"><StatCard title="Completed scans" value={scans.length} sub="Available for comparison" icon={Activity}/><StatCard title="Websites with history" value={[...groups.values()].filter(items=>items.length>1).length} sub="At least two completed scans" icon={Globe}/><StatCard title="Observed status changes" value={comparisons.length} sub="Based on matching check identifiers" icon={RefreshCw} tone="violet"/><StatCard title="Comparison coverage" value={groups.size?`${Math.round([...groups.values()].filter(items=>items.length>1).length/groups.size*100)}%`:'—'} sub="Websites with comparable scans" icon={CheckCircle2} tone="cyan"/></div><div className="panel list-panel"><div className="panel-heading"><div><h3>Observed check changes</h3><p>Only checks present in both of the two latest completed scans are compared.</p></div></div>{comparisons.length?<div className="table-scroll"><table><thead><tr><th>Website</th><th>Check</th><th>Previous status</th><th>Latest status</th><th>Latest scan</th><th>Observed</th></tr></thead><tbody>{comparisons.map(c=><tr key={c.id}><td><b>{c.website}</b></td><td>{c.label}</td><td><span className={'badge '+String(c.before).toLowerCase()}>{c.before}</span></td><td><span className={'badge '+String(c.after).toLowerCase()}>{c.after}</span></td><td><code>{String(c.scanId).slice(-8)}</code></td><td>{new Date(c.date).toLocaleString()}</td></tr>)}</tbody></table></div>:<Empty title="No status changes found" text="Changes appear after at least two completed scans contain the same check with different statuses. This page compares saved scan results; it does not independently monitor websites."/>}</div></>}</>;
}

export function SettingsPage(){const{user,refresh,setUser}=useAuth();const[busy,setBusy]=useState(false);async function profile(e){e.preventDefault();const f=new FormData(e.currentTarget);setBusy(true);try{const r=await api.patch('/auth/profile',{name:f.get('name'),preferences:{theme:f.get('theme'),emailNotifications:f.get('emailNotifications')==='on'}});setUser(r.data.data.user);toast.success('Settings saved')}catch(e){toast.error(e.response?.data?.message||'Settings could not be saved')}finally{setBusy(false)}}async function password(e){e.preventDefault();const f=new FormData(e.currentTarget);if(f.get('newPassword')!==f.get('confirmPassword'))return toast.error('New passwords do not match');try{await api.patch('/auth/password',{currentPassword:f.get('currentPassword'),newPassword:f.get('newPassword')});e.currentTarget.reset();toast.success('Password changed')}catch(e){toast.error(e.response?.data?.message||'Password change failed')}}return <><PageHeader eyebrow="PREFERENCES & ACCESS" title="Account settings" subtitle="Manage your profile, display preferences and account security."/><div className="settings-grid"><form className="panel form-panel" onSubmit={profile}><div className="form-section"><h3>Profile preferences</h3><p>Changes are saved to your account.</p><label>Full name<input name="name" defaultValue={user?.name} required minLength="2"/></label><label>Email address<input value={user?.email||''} disabled/><small>Email changes are disabled in this version.</small></label><label>Appearance<select name="theme" defaultValue={user?.preferences?.theme||'dark'}><option value="dark">Dark</option><option value="light">Light</option></select></label><label className="check-label"><input type="checkbox" name="emailNotifications" defaultChecked={user?.preferences?.emailNotifications!==false}/> Email notifications preference</label><div className="form-actions"><button className="btn primary" disabled={busy}>Save preferences</button></div></div></form><form className="panel form-panel" onSubmit={password}><div className="form-section"><h3>Change password</h3><p>Use a unique password with at least 8 characters.</p><label>Current password<input name="currentPassword" type="password" required autoComplete="current-password"/></label><label>New password<input name="newPassword" type="password" required minLength="8" autoComplete="new-password"/></label><label>Confirm new password<input name="confirmPassword" type="password" required minLength="8" autoComplete="new-password"/></label><div className="form-actions"><button className="btn primary">Update password</button></div></div></form><div className="panel security-summary"><div className="tip-icon"><LockKeyhole/></div><h3>Session security</h3><p>Your session uses a server-managed HttpOnly cookie. The browser JavaScript cannot read the session token.</p><div className="security-line"><span>Account role</span><b>{user?.role||'user'}</b></div><div className="security-line"><span>Session</span><span className="badge completed">Authenticated</span></div></div></div></>}
export function CommandPalette({onClose}){const[query,setQuery]=useState('');const navigate=useNavigate();const input=useRef(null);const actions=[...nav.map(([label,path,Icon])=>({label,path,Icon,detail:'Open '+label.toLowerCase()})),{label:'Add a website',path:'/app/websites/new',Icon:Plus,detail:'Register a website to monitor'},{label:'Run a security scan',path:'/app/scans',Icon:ScanLine,detail:'Start a passive security scan'},{label:'Account settings',path:'/app/settings',Icon:Settings,detail:'Profile, preferences and password'}];const filtered=actions.filter(a=>(a.label+' '+a.detail).toLowerCase().includes(query.toLowerCase()));useEffect(()=>{input.current?.focus()},[]);return <div className="command-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><motion.div className="command-palette" initial={{opacity:0,y:-10,scale:.98}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:-6}} role="dialog" aria-modal="true" aria-label="Quick search"><div className="command-search"><Search size={19}/><input ref={input} value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search pages, tools and actions…"/><kbd>ESC</kbd></div><div className="command-caption">QUICK NAVIGATION</div><div className="command-results">{filtered.length?filtered.map((a,i)=><button key={a.path+'-'+i} className="command-result" onClick={()=>{navigate(a.path);onClose()}}><span className="command-result-icon"><a.Icon size={17}/></span><span><b>{a.label}</b><small>{a.detail}</small></span><ChevronRight size={16}/></button>):<div className="command-empty">No matching pages or actions. Try another search.</div>}</div><div className="command-footer"><span><kbd>↵</kbd> Open destination</span><span><kbd>ESC</kbd> Close</span></div></motion.div></div>}
export function NotFound({publicPage=false}){return <div className="not-found"><div className="not-found-code">404</div><h1>Page not found</h1><p>The page you're looking for doesn't exist or may have moved.</p><Link className="btn primary" to={publicPage?'/':'/app'}>Return to {publicPage?'home':'workspace'} <ChevronRight size={16}/></Link></div>}
export default App;
